data.filter(~col("mw").is_null() & ~col("source").is_in(["Load", "Residual load", "Renewable share of load", "Renewable share of generation", "Cross border electricity trading"])).group_by("source").agg(mean_mw = col("mw").mean().round(0), peak_mw = col("mw").max(), quarters = len()).with_columns(share_pct = (col("mean_mw") / col("mean_mw").sum() * 100).round(1)).sort("mean_mw", descending=True)